//! Real native widget rendering for all families, including narrow cards and
//! absent data. Captures are generated by Iced's actual renderer, not mockups.
use super::*;
use crate::desktop_theme::Family;
use crate::native_test::Native;
use cosmic::{
    Application,
    iced::{
        Point, Size,
        widget::{pin, stack},
    },
};

fn theme_view(cards: &Cards, widget: Widget) -> Element<'_, Message> {
    match widget {
        Widget::Clock => cards.clock(),
        Widget::Weather => cards.weather_card(),
        Widget::Calendar => cards.calendar_card(),
        Widget::Devbox => cards.devbox(),
        Widget::Projects => cards.projects_card(),
        Widget::Glance => cards.glance(),
        _ => cards.tool_card(widget),
    }
}

#[test]
fn shared_theme_native_widgets_remain_visible_on_light_and_dark_wallpapers() {
    let today = Local::now().date_naive();
    let mut cfg = Config::default();
    cfg.weather.show_dew_point = true;
    cfg.glance.enabled = true;
    cfg.glance.show_tomorrow = true;
    cfg.location = Some(Location {
        name: "Sample city".into(),
        latitude: 0.,
        longitude: 0.,
        timezone: None,
    });
    cfg.glance.density = crate::config::GlanceDensity::Compact;
    let (mut cards, _) = Cards::init(Core::default(), cfg);
    cards.weather = Some(Weather {
        current: data::Current {
            temperature_2m: 21.,
            apparent_temperature: 20.,
            weather_code: 2,
            wind_speed_10m: 8.,
            relative_humidity_2m: 52.,
            dew_point_2m: Some(10.8),
            is_day: 1,
        },
        daily: data::Daily {
            time: (0..3)
                .map(|n| (today + Days::days(n)).to_string())
                .collect(),
            temperature_2m_max: vec![23., 22., 24.],
            temperature_2m_min: vec![14., 13., 15.],
            weather_code: vec![2, 3, 0],
            precipitation_probability_max: vec![Some(10.), Some(25.), None],
        },
    });
    let calendar = CalendarData {
        events: vec![CalendarEvent {
            title: "Design review · sample agenda with an inline meeting link".into(),
            start: today.to_string(),
            end: (today + Days::days(1)).to_string(),
            all_day: true,
            url: "https://example.com/event".into(),
            meeting_url: Some("https://example.com/join".into()),
            ..Default::default()
        }],
        ..Default::default()
    };
    cards.calendar = Some(calendar.clone());
    cards.calendar_today = Some(calendar);
    cards.tools.note = Ok(crate::tools::notes::Note {
        text: "# Today\n- [x] Choose a shared theme\n- [ ] Review the calendar".into(),
        ..Default::default()
    });
    for family in Family::ALL {
        cards.config.appearance.family = Some(family);
        let (opacity, radius, border) = family.geometry();
        cards.config.appearance.opacity = opacity;
        cards.config.appearance.corner_radius = radius;
        cards.config.appearance.border_opacity = border;
        for light in [false, true] {
            cards.config.appearance.wallpaper_light = light;
            for widget in Widget::ALL {
                cards
                    .config
                    .widget_sizes
                    .insert(widget.key().into(), [280., 260.]);
            }
            let theme = if light {
                cosmic::Theme::light()
            } else {
                cosmic::Theme::dark()
            };
            let mut native = Native::new(Size::new(920., 880.));
            let color = if light {
                Color::from_rgb8(239, 236, 226)
            } else {
                Color::from_rgb8(24, 35, 34)
            };
            if family == Family::Bare && light {
                let mut cell = Native::new(Size::new(280., 260.));
                let pixels = cell.render(cards.calendar_card(), &theme);
                let opaque_black = pixels
                    .chunks_exact(4)
                    .filter(|p| p[0] < 16 && p[1] < 16 && p[2] < 16 && p[3] > 250)
                    .count();
                assert!(
                    opaque_black < 32,
                    "selected dates must not put opaque black behind Bare's dark text"
                );
            }
            let mut layers = Vec::new();
            for (index, widget) in Widget::ALL.into_iter().enumerate() {
                layers.push(
                    pin(container(theme_view(&cards, widget))
                        .width(280.)
                        .height(260.))
                    .position(Point::new(
                        20. + (index % 3) as f32 * 300.,
                        20. + (index / 3) as f32 * 280.,
                    ))
                    .into(),
                );
            }
            let view = container(stack(layers).width(920.).height(880.)).class(
                cosmic::theme::Container::custom(move |_| cosmic::iced::widget::container::Style {
                    background: Some(Background::Color(color)),
                    ..Default::default()
                }),
            );
            native.capture(
                view.into(),
                &theme,
                &format!(
                    "theme-{}-widgets-{}",
                    family.id(),
                    if light { "light" } else { "dark" }
                ),
            );
            for widget in [Widget::Weather, Widget::Glance, Widget::Clock] {
                let size = if widget == Widget::Clock {
                    [160., 100.]
                } else {
                    [260., 260.]
                };
                cards.config.widget_sizes.insert(widget.key().into(), size);
                let mut native = Native::new(Size::new(size[0], size[1]));
                let pixels = native.render(theme_view(&cards, widget), &theme);
                assert!(
                    pixels.chunks_exact(4).filter(|p| p[3] > 128).count() > 80,
                    "{family:?} {widget:?} must remain visible"
                );
                native.capture(
                    theme_view(&cards, widget),
                    &theme,
                    &format!(
                        "theme-{}-{}-narrow-{}",
                        family.id(),
                        widget.key(),
                        if light { "light" } else { "dark" }
                    ),
                );
            }
        }
    }
}
